const UnselectedSubLevel = props => {
  const { classes } = style()
  const [hover, setHover] = useState(false)
  return (
    <div
      className={classes.wrapper}
      onMouseEnter={() => {
        setHover(true)
      }}
      onMouseLeave={() => {
        setHover(false)
      }}
      onClick={() => {
        if (props.level > props.currentLevel) {
          props.open(props.level)
        } else {
          props.close(props.level)
        }
      }}
    >
      {hover && <SelectedSubLevel level={props.level} />}
      {!hover && (
        <svg
          width="18"
          height="16"
          viewBox="0 0 18 16"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
          style={{ cursor: 'pointer' }}
          data-test={`unselected-sublevel-${props.level}`}
        >
          <path
            d="M1.02196 1.55036C0.583681 0.885474 1.06054 0 1.85688 0H8V8V16H1.85688C1.06054 16 0.583682 15.1145 1.02196 14.4496L4.54782 9.10072C4.98802 8.43292 4.98801 7.56708 4.54782 6.89928L1.02196 1.55036Z"
            fill="#504C4B"
            fillOpacity="0.1"
          />
          <path
            d="M8 0H10.5C11.4443 0 12.3334 0.444583 12.9 1.2L17.1 6.8C17.6333 7.51111 17.6333 8.48889 17.1 9.2L12.9 14.8C12.3334 15.5554 11.4443 16 10.5 16H8V8V0Z"
            fill="#504C4B"
            fillOpacity="0.1"
          />
        </svg>
      )}
    </div>
  )
}

