const RoadmapBreadCrumb = props => {
  const { classes } = style()
  return (
    <div style={{ position: 'absolute', zIndex: 1005, width: '100%' }}>
      <div className={classNames([classes.wrapper, classes.sticky])}>
        {props.maxLevel > 1 ? (
          props.level === 1 ? (
            <SelectedLevelA
              close={() => {
                props.close(props.task, 1)
              }}
            />
          ) : (
            <UnselectedLevelA />
          )
        ) : null}
        {new Array(props.maxLevel - 1).fill(0).map((currentElem, index) => {
          if (index === 0 || index === props.maxLevel - 1) {
            return null //skip level A
          }

          if (index === props.level - 1) {
            return (
              <SelectedSubLevel
                level={props.level}
                close={level => props.close(props.task, level)}
              />
            )
          }
          return (
            <UnselectedSubLevel
              level={index + 1}
              currentLevel={props.level}
              open={level => props.open(props.task, level)}
              close={level => props.close(props.task, level)}
            />
          )
        })}
        {props.level === props.maxLevel ? (
          <SelectedEndCap level={props.level} />
        ) : (
          <UnselectedEndCap
            level={props.maxLevel}
            open={level => props.open(props.task, level)}
            close={() => {
              props.close(props.task, props.level)
            }}
            isFullyExpanded={props.isFullyExpanded}
          />
        )}
      </div>
    </div>
  )
}

export default RoadmapBreadCrumb
